import { defineConfig, mergeConfig } from 'vitest/config';
import nodeSharedConfig from '../../../../vitest.shared';
import domSharedConfig from '../../../../vitest.dom.shared';

// Dual preset — this package has logic specs that vi.mock('@angular/core') or
// vi.mock('@memberjunction/core'); those mocks break under the Angular AOT compile path, so
// they stay on the fast node preset while *.dom.test.ts run under the jsdom/Angular DOM
// preset. The two projects are kept disjoint by EXCLUSION (mergeConfig concatenates the
// include/exclude arrays). Generated by scripts/gen-dom-stub.mjs. See
// guides/ANGULAR_TESTING_GUIDE.md §3b.
export default defineConfig({
  test: {
    projects: [
      mergeConfig(
        nodeSharedConfig,
        defineConfig({
          test: { name: 'dashboards (node)', environment: 'node', exclude: ['**/*.dom.test.ts'] },
        }),
      ),
      mergeConfig(
        domSharedConfig,
        defineConfig({
          // The dom shared config contributes a broad `src/**/*.test.ts` include; `!(*.dom).test.ts`
          // excludes every non-`.dom` test so node-only logic specs (which may vi.mock @angular/core
          // and live OUTSIDE __tests__) don't get pulled through the Angular AOT path.
          test: { name: 'dashboards (dom)', include: ['src/**/*.dom.test.ts'], exclude: ['**/__tests__/**', '**/!(*.dom).test.ts'] },
        }),
      ),
    ],
  },
});
